/**
 * TestUtils.js
 * Utility test suite for testing individual components directly in the GAS Editor.
 */

/**
 * 1. Tests Config validation.
 * Checks if Script Properties are set and validates CONFIG_JSON schema.
 */
function testValidateConfig() {
  console.log("--- 1. Testing Script Properties ---");
  var props = PropertiesService.getScriptProperties().getProperties();
  console.log("TELEGRAM_BOT_TOKEN: " + (props.TELEGRAM_BOT_TOKEN ? "✅ Set" : "❌ Missing"));
  console.log("GEMINI_API_KEY: " + (props.GEMINI_API_KEY ? "✅ Set" : "❌ Missing"));
  console.log("ADMIN_CHAT_ID: " + (props.ADMIN_CHAT_ID ? "✅ Set (" + props.ADMIN_CHAT_ID + ")" : "❌ Missing"));
  console.log("WEB_APP_URL: " + (props.WEB_APP_URL ? "✅ Set" : "⚠️ Optional"));

  console.log("\n--- 2. Validating CONFIG_JSON ---");
  var config = Config.getConfig();
  if (!config.properties || !Array.isArray(config.properties)) {
    console.error("❌ 'properties' array is missing or invalid in CONFIG_JSON!");
    return;
  }

  console.log("Found " + config.properties.length + " properties configured.");
  config.properties.forEach(function (p, idx) {
    console.log("Property " + (idx + 1) + ": " + p.address_name + " (ID: " + p.property_id + ")");
    console.log("  Sheet ID: " + (p.google_sheet_id || '⚠️ Empty'));
    console.log("  Default Chat ID: " + (p.source_chat_id || '⚠️ None'));
    console.log("  Meters count: " + ((p.meters && p.meters.length) || 0));

    if (p.meters) {
      p.meters.forEach(function (m) {
        var sharedNote = (m.shared_targets && m.shared_targets.length > 0)
          ? " [Shared with " + m.shared_targets.length + " property(ies)]"
          : "";
        console.log("    - " + m.name_uk + " (" + m.type + ") -> Col " + m.target_column + sharedNote);
      });
    }
  });

  console.log("\nDistinct source chats: " + JSON.stringify(Config.getDistinctSourceChats()));
}

/**
 * 2. Sends a mock Admin Confirmation Card to Admin DM to test Telegram UI buttons.
 */
function testSendMockAdminCard() {
  var config = Config.getConfig();
  if (!config.properties || config.properties.length === 0) {
    console.error("No properties configured.");
    return;
  }

  var firstMeter = config.properties[0].meters[0];
  var mockSession = {
    sourceChatId: config.properties[0].source_chat_id || 123456789,
    sourceMessageId: 1,
    chatTitle: "Тестовий Чат Будинку",
    senderId: 99999999,
    senderUsername: "test_tenant",
    senderName: "Орендар Тестовий",
    photoFileId: null, // No photo for mock test
    recognized: true,
    meter_id: firstMeter.meter_id,
    meter_type: firstMeter.type,
    meter_code: firstMeter.code,
    reading_value: 4829.5,
    confidence_score: 0.96,
    issue_notes: "Тестове повідомлення перевірки інтерфейсу"
  };

  var sessionId = StateService.saveSession(mockSession);
  mockSession.sessionId = sessionId;

  AdminHandler.sendConfirmationCard(mockSession);
  console.log("Mock card sent to Admin with Session ID: " + sessionId);
}

/**
 * 3. Tests Gemini Prompt construction for a chat.
 */
function testGeminiPrompt() {
  var chatIds = Config.getDistinctSourceChats();
  var testChatId = chatIds.length > 0 ? chatIds[0] : 0;
  var candidateMeters = Config.getMetersForChat(testChatId);
  var prompt = Gemini.buildSystemPrompt(candidateMeters);

  console.log("Generated prompt for Chat " + testChatId + ":\n" + prompt);
}

/**
 * 4. Lists all Gemini models currently supported by your API key.
 */
function testListGeminiModels() {
  console.log("Querying Gemini API for supported models...");
  var models = Gemini.listAvailableModels();
  console.log("Found " + models.length + " model(s) supporting generateContent:\n" + JSON.stringify(models, null, 2));

  var best = Gemini.discoverBestModel();
  console.log("Recommended Flash model: " + best);
}

/**
 * 5. Tests Gemini AI vision analysis directly on a real meter sample photo (electricity meter #007509124014617).
 * Run this function in the GAS toolbar to verify recognition without sending anything via Telegram.
 */
function testAnalyzeSampleMeter() {
  console.log('--- Testing Gemini Vision with real sample photo ---');
  var b64Data = '"' + '' + '"';
  var bytes = Utilities.base64Decode('');
  var blob = Utilities.newBlob(bytes, 'image/jpeg', 'sample_meter.jpg');

  var mockCandidates = [
    {
      property: { address_name: "вул. Хрещатик, 10" },
      meter: {
        meter_id: "electricity_main",
        name_uk: "Електроенергія",
        type: "electricity",
        code: "007509124014617",
        description_for_ai: "Електронний лічильник Енергомера"
      }
    }
  ];

  console.log('Sending sample image to Gemini...');
  var result = Gemini.analyzeMeterImage(blob, mockCandidates);
  console.log('Gemini Analysis Result:' + JSON.stringify(result, null, 2));

  if (result.recognized) {
    console.log('✅ RECOGNITION SUCCESSFUL!');
    console.log('• Meter Type: ' + result.meter_type);
    console.log('• Serial: ' + result.meter_code);
    console.log('• Reading Value: ' + result.reading_value);
    console.log('• Confidence: ' + (result.confidence_score * 100) + '%');
  } else {
    console.error('❌ RECOGNITION FAILED: ' + result.issue_notes);
  }
}
